export function inventoryStatus(card,quantity,goldExchange=false,mode='Same Rarity'){if(!Number.isInteger(quantity)||quantity<0)throw Error('Invalid quantity');return {owned:quantity>0,missing:quantity===0,duplicates:Math.max(0,quantity-1),tradeable:quantity>=2&&mode!=='No Trading',label:quantity===0?'LF':quantity===1||mode==='No Trading'?'Owned':'FT'};}
export function albumShareText(data,inventory,profile,mode,trades,gold=false,publicLink=''){if(!['Same Rarity','Flexible Rarity','Any Rarity','No Trading'].includes(mode)||!Number.isInteger(trades)||trades<0||trades>3)throw Error('Choose a valid trade mode and 0–3 trades left.');const clean=s=>String(s||'Not set').replace(/[\r\n`]/g,' ').trim();if(mode==='No Trading'){const collected=data.cards.filter(c=>(inventory.get(c.number)?.quantity||0)>0),goldCount=collected.filter(c=>c.gold).length;return ['🎴 **Autumn Tales | `'+clean(profile.discord_username)+'` | ID: `'+clean(profile.game_id)+'`**','Mode: No Trading','Collected: '+collected.length+'/'+data.cards.length+' · Gold: '+goldCount+'/17',...(publicLink?['Album: '+publicLink]:[])].join('\n');}const lines=['🎴 **Autumn Tales | `'+clean(profile.discord_username)+'` | ID: `'+clean(profile.game_id)+'`**','🤝 Mode: '+mode,'⏳ Trades left today: '+trades+'/3','','🔍 **LF (Looking For):**'];const rows=kind=>{const result=[];for(let stars=1;stars<=5;stars++){const cards=data.cards.filter(c=>c.stars===stars).filter(c=>{const q=inventory.get(c.number)?.quantity||0;return kind==='lf'?q===0:q>=2;}).map(c=>c.number+(c.gold?'G':''));if(cards.length)result.push('★'.repeat(stars)+': '+cards.join(', '));}return result;};const lf=rows('lf'),ft=rows('ft');lines.push(...(lf.length?lf:['None']),'','📦 **FT (For Trade):**',...(ft.length?ft:['None']),'','DM me or reply!');return lines.join('\n');}

